coro-go-forms.code:
// 形式 1：调用一个已声明的函数
var t1 = go worker(0, channel)

// 内联逻辑：lambda 也必须形成完整调用，并显式传参
var t2 = go fn(d: JSON.Object) -> i64 {
    return d.value * 2
}(payload)

// 无参数内联逻辑仍写成零参 lambda 调用；不存在 go { ... } 语法
var t3 = go fn() -> i64 {
    return compute()
}()

// 可选调试名称
var named = go(name: "worker-1") worker(1, channel)

